```

**Width Control:**
- **Large (default):** Unconstrained, fills available space
- **Medium/Small:** Constrained via `PREVIEW_WIDTHS` ([main.ts.tmpl:1033-1037](packages/scaffold/templates/canvas-theme-editor/src/main.ts.tmpl#L1033-L1037)):
  ```typescript
  const PREVIEW_WIDTHS: Record<string, string> = {
    medium: "var(--instui-breakpoints-md)",  // Canvas-responsive breakpoint
    small: "var(--instui-breakpoints-sm)",
  };

  function applyPreviewWidth(): void {
    if (selectedPreviewWidth === "large") return;
    if (fullscreen) {
      previewFrame.style.maxWidth = PREVIEW_WIDTHS[selectedPreviewWidth];
